#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

void printInt128(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 nInput, mInput;
    cin >> nInput >> mInput;

    i128 n = nInput;
    i128 m = mInput;

    auto possible = [&](i128 x) {
        i128 multiplesOf2 = x / 2;
        i128 multiplesOf3 = x / 3;
        i128 distinctMultiples = multiplesOf2 + multiplesOf3 - x / 6;

        return multiplesOf2 >= n &&
               multiplesOf3 >= m &&
               distinctMultiples >= n + m;
    };

    i128 low = 0;
    i128 high = 1;

    while (!possible(high))
        high *= 2;

    while (low < high) {
        i128 mid = low + (high - low) / 2;
        if (possible(mid))
            high = mid;
        else
            low = mid + 1;
    }

    printInt128(low);
    return 0;
}

