int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m;
    cin >> n >> m;

    auto feasible = [&](int64 x) {
        return x / 2 >= n &&
               x / 3 >= m &&
               x / 2 + x / 3 - x / 6 >= n + m;
    };

    int64 low = 0, high = 1;
    while (!feasible(high)) high *= 2;

    while (low + 1 < high) {
        int64 mid = low + (high - low) / 2;
        if (feasible(mid))
            high = mid;
        else
            low = mid;
    }

    cout << high;
    return 0;
