int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m;
    cin >> n >> m;

    int64 low = 0, high = LLONG_MAX;

    auto possible = [&](int64 x) {
        i128 even = x / 2;
        i128 divisibleByThree = x / 3;
        i128 distinct = even + divisibleByThree - x / 6;

        return even >= n &&
               divisibleByThree >= m &&
               distinct >= static_cast<i128>(n) + m;
    };

    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (possible(mid))
            high = mid;
        else
            low = mid + 1;
    }

    cout << low;
    return 0;
}

